import{useEffect,useState}from'react';import{Activity,AlertTriangle,ChevronRight,Loader2,RefreshCw,UsersRound}from'lucide-react';import{getClientEngagement,getEngagementProjections}from'../../lib/practiceOperationsApi';
const tones={HIGH:'bg-emerald-50 text-emerald-800',MODERATE:'bg-blue-50 text-blue-800',NEEDS_ATTENTION:'bg-amber-50 text-amber-900',INSUFFICIENT_DATA:'bg-slate-100 text-slate-700'};
export function EngagementPanel({clientId}){const[data,setData]=useState(null),[state,setState]=useState('loading'),[error,setError]=useState('');const load=async()=>{setState('loading');try{setData(await getClientEngagement(clientId));setState('ready')}catch(reason){setError(reason.message||'Engagement could not load.');setState('error')}};useEffect(()=>{void load()},[clientId]);if(state==='loading')return <div role="status" className="grid min-h-32 place-items-center"><Loader2 className="animate-spin"/><span className="sr-only">Loading engagement</span></div>;if(state==='error')return <div role="alert" className="rounded-xl bg-red-50 p-4 text-red-800">{error}<button onClick={load} className="ml-2 min-h-11"><RefreshCw className="inline"/> Retry</button></div>;return <section className="rounded-3xl border bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-wider text-blue-700">Engagement</p><h3 className="mt-1 text-xl font-bold">Operational engagement</h3></div><span className={`rounded-full px-3 py-2 text-xs font-bold ${tones[data.state]}`}>{data.state.replaceAll('_',' ')}</span></div><p className="mt-3 text-sm text-slate-500">{data.explanation}</p><h4 className="mt-5 font-semibold">Why?</h4>{data.reasons.length?<ul className="mt-2 space-y-2">{data.reasons.map(reason=><li key={reason.code} className="rounded-xl bg-slate-50 p-3 text-sm"><strong>{reason.code.replaceAll('_',' ')}</strong><span className="mt-1 block text-slate-600">{reason.reason}</span><small className="text-slate-400">Source: {reason.source}</small></li>)}</ul>:<p className="mt-2 rounded-xl bg-slate-50 p-3 text-sm text-slate-500">{data.state==='INSUFFICIENT_DATA'?'Insufficient confirmed activity to classify engagement.':'No disengagement indicators are confirmed.'}</p>}<p className="mt-4 text-xs text-slate-500">Last meaningful activity: {data.last_meaningful_activity?new Date(data.last_meaningful_activity).toLocaleString():'Not available'}</p></section>}
export function DisengagementDashboard({clients,onOpen}){const[data,setData]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState('');useEffect(()=>{let live=true;(async()=>{setState('loading');try{if(!clients.length){setData([]);setState('ready');return}const result=await getEngagementProjections(clients.map(item=>item.id));if(live){setData(result.items||[]);setState('ready')}}catch(reason){if(live){setError(reason.message||'Engagement projections could not load.');setState('error')}}})();return()=>{live=false}},[clients]);if(state==='loading')return <section aria-label="Loading engagement projections" className="min-h-40 animate-pulse rounded-3xl bg-white"/>;if(state==='error')return <section role="alert" className="rounded-3xl bg-red-50 p-5 text-red-800"><AlertTriangle className="mr-2 inline"/> {error}. No client is classified as disengaging.</section>;const clientById=new Map(clients.map(item=>[item.id,item]));const attention=data.filter(item=>item.state==='NEEDS_ATTENTION');return <section className="rounded-3xl border bg-white p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-wider text-amber-700">Engagement</p><h3 className="mt-1 text-lg font-bold">Clients potentially disengaging</h3></div><UsersRound className="text-amber-700"/></div>{attention.length?<div className="mt-4 divide-y">{attention.slice(0,5).map(item=><button key={item.client_id} onClick={()=>onOpen(clientById.get(item.client_id))} className="flex min-h-20 w-full items-center justify-between gap-3 py-3 text-left"><span><strong>{clientById.get(item.client_id)?.displayName||'Client'}</strong><small className="mt-1 block text-slate-500">{item.reasons[0]?.reason}</small><small className="block text-slate-400">Last activity: {item.last_meaningful_activity?new Date(item.last_meaningful_activity).toLocaleDateString():'Not available'}</small></span><ChevronRight/></button>)}</div>:<p className="mt-4 rounded-2xl border border-dashed p-5 text-center text-sm text-slate-500">No clients are confirmed as needing engagement attention.</p>}</section>}
